 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if len(set(grid[r])) == 1]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    # Uniform full-length lines mark boundaries between repeated regions.
    row_cuts = [-1] + rows + [h]
    col_cuts = [-1] + cols + [w]
    row_spans = [(row_cuts[i] + 1, row_cuts[i + 1]) for i in range(len(row_cuts)-1) if row_cuts[i+1] > row_cuts[i]+1]
    col_spans = [(col_cuts[i] + 1, col_cuts[i + 1]) for i in range(len(col_cuts)-1) if col_cuts[i+1] > col_cuts[i]+1]
    # Background is the most frequent color not used by full-length divider lines.
    divider_colors = {grid[r][0] for r in rows} | {grid[0][c] for c in cols}
    counts = Counter(v for row in grid for v in row if v not in divider_colors)
    bg = counts.most_common(1)[0][0]
    blocks = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            blocks.append((r0, r1, c0, c1))
    source = max(blocks, key=lambda b: sum(grid[r][c] != bg for r in range(b[0], b[1]) for c in range(b[2], b[3])))
    sr0, sr1, sc0, sc1 = source
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]
    out = [row[:] for row in grid]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if r1-r0 == len(pattern) and c1-c0 == len(pattern[0]):
                for dr in range(r1-r0):
                    for dc in range(c1-c0):
                        out[r0+dr][c0+dc] = pattern[dr][dc]
    return out
